<template>
  <div ref="root" class="design-picker" @focusout="onFocusOut">
    <button ref="trigger" class="design-picker-trigger" type="button" data-press-intent="custom"
      aria-haspopup="listbox" :aria-expanded="open" :aria-controls="listId"
      :aria-label="`Design detail, ${active.label}`" @click="toggle" @keydown="onTriggerKey">
      <ExhibitionFeatureIcon :feature="active.id" />
      <span class="design-picker-current"><span>{{ activeGroup.title }}</span><strong>{{ active.label }}</strong></span>
      <svg class="design-picker-chevron" :class="{ 'is-open': open }" viewBox="0 0 20 20" aria-hidden="true"><path d="m6 8 4 4 4-4" /></svg>
    </button>
    <Transition name="design-picker" :css="!keyboardInteraction">
      <div v-if="open" :id="listId" ref="menu" class="design-picker-menu" :class="{ 'opens-up': opensUp }"
        :style="{ '--picker-space': `${availableSpace}px` }" role="listbox" aria-label="Design detail" @keydown="onMenuKey">
        <div v-for="group in studies" :key="group.id" class="design-picker-group" role="group" :aria-labelledby="`${listId}-${group.id}`">
          <div :id="`${listId}-${group.id}`" class="design-picker-group-label">{{ group.title }}</div>
          <div class="design-picker-options">
            <button v-for="feature in group.features" :key="feature.id" type="button" role="option" data-press-intent="custom"
              :data-feature="feature.id" :aria-selected="value === feature.id" :tabindex="focusedId === feature.id ? 0 : -1"
              @focus="focusedId = feature.id" @click="choose(feature.id)">
              <ExhibitionFeatureIcon :feature="feature.id" /><span>{{ feature.label }}</span>
              <svg class="design-picker-check" :class="{ 'is-selected': value === feature.id }" viewBox="0 0 16 16" aria-hidden="true"><path d="m3 8 3 3 7-7" /></svg>
            </button>
          </div>
        </div>
      </div>
    </Transition>
  </div>
</template>

<script>
import ExhibitionFeatureIcon from './ExhibitionFeatureIcon.vue';

export default {
  components: { ExhibitionFeatureIcon },
  props: { studies: { type: Array, required: true }, value: { type: String, required: true } },
  emits: ['select'],
  data: () => ({ open: false, focusedId: '', opensUp: false, availableSpace: 400, keyboardInteraction: false }),
  computed: {
    items() { return this.studies.flatMap(group => group.features); },
    active() { return this.items.find(feature => feature.id === this.value) || this.items[0]; },
    activeGroup() { return this.studies.find(group => group.features.some(feature => feature.id === this.active.id)); },
    listId() { return `exhibition-design-options-${this.$.uid}`; },
  },
  mounted() {
    document.addEventListener('pointerdown', this.onOutsidePointer, true);
    window.addEventListener('resize', this.onResize);
  },
  beforeUnmount() {
    document.removeEventListener('pointerdown', this.onOutsidePointer, true);
    window.removeEventListener('resize', this.onResize);
  },
  methods: {
    async show(keyboard = false) {
      this.keyboardInteraction = keyboard;
      this.focusedId = this.active.id;
      const rect = this.$refs.trigger.getBoundingClientRect();
      const below = window.innerHeight - rect.bottom - 12;
      const above = rect.top - 84;
      const expectedHeight = this.studies.length * 140 + 16;
      this.opensUp = below < expectedHeight && above > below;
      this.availableSpace = Math.max(120, this.opensUp ? above : below);
      this.open = true;
      await this.$nextTick();
      if (keyboard) this.focusOption(this.active.id);
    },
    toggle() { if (this.open) this.close(); else this.show(); },
    close(restoreFocus = false) {
      this.open = false;
      if (restoreFocus) this.$refs.trigger.focus({ preventScroll: true });
    },
    choose(id) { this.$emit('select', id); this.close(true); },
    focusOption(id) {
      this.focusedId = id;
      this.$refs.menu?.querySelector(`[data-feature="${id}"]`)?.focus({ preventScroll: true });
    },
    onTriggerKey(event) {
      if (['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(event.key)) {
        event.preventDefault();
        if (this.open) this.close(true); else this.show(true);
      } else if (event.key === 'Escape' && this.open) { event.preventDefault(); this.close(true); }
    },
    onMenuKey(event) {
      this.keyboardInteraction = true;
      if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); this.close(true); return; }
      const index = this.items.findIndex(feature => feature.id === this.focusedId);
      const step = { ArrowDown: 2, ArrowUp: -2, ArrowRight: 1, ArrowLeft: -1 }[event.key];
      let next = step == null ? null : Math.max(0, Math.min(this.items.length - 1, index + step));
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = this.items.length - 1;
      if (next != null) { event.preventDefault(); this.focusOption(this.items[next].id); }
      else if (event.key.length === 1 && /\S/.test(event.key)) {
        const ordered = [...this.items.slice(index + 1), ...this.items.slice(0, index + 1)];
        const match = ordered.find(feature => feature.label.toLowerCase().startsWith(event.key.toLowerCase()));
        if (match) { event.preventDefault(); this.focusOption(match.id); }
      }
    },
    onOutsidePointer(event) { if (this.open && !this.$refs.root.contains(event.target)) this.close(); },
    onFocusOut(event) { if (event.relatedTarget && !this.$refs.root.contains(event.relatedTarget)) this.close(); },
    onResize() { if (this.open) this.close(); },
  },
};
</script>

