<template>
  <figure class="knowledge-search-trail" :class="{ 'reduce-motion': reducedMotion }">
    <svg viewBox="0 0 360 160" aria-hidden="true" focusable="false">
      <g
        v-for="branch in branches"
        :key="branch.id"
        class="trail-branch"
        :class="{ found: foundSources.includes(branch.id), active: activeId === branch.id }"
      >
        <path class="branch-line" :d="branch.path" />
        <path class="branch-found-line" :d="branch.path" />
        <circle
          v-if="activeId === branch.id && !reducedMotion"
          class="branch-pulse"
          r="3"
          :style="{ offsetPath: `path('${branch.path}')` }"
        />

        <g :transform="`translate(192 ${branch.y - 18})`">
          <rect class="trail-source-paper" x="0.5" y="0.5" width="157" height="35" rx="7" />
          <rect class="source-found-paper" x="0.5" y="0.5" width="157" height="35" rx="7" />
          <g class="source-icon" transform="translate(11 10)">
            <path d="M 1 0.75 H 8 L 12 4.75 V 15.25 H 1 Z M 8 0.75 V 4.75 H 12" />
            <path d="M 4 8 H 9 M 4 11 H 8" />
          </g>
          <text class="source-label" x="33" y="22">{{ branch.label }}</text>
          <g class="source-check" transform="translate(142 18)">
            <circle r="6.5" />
            <path d="M -2.6 0 L -0.7 1.9 L 2.8 -2" />
          </g>
        </g>
      </g>

      <g class="source-hub" :class="{ searching: activeId }">
        <circle class="hub-ring" cx="48" cy="80" r="25" />
        <circle class="hub-paper" cx="48" cy="80" r="20" />
        <g class="hub-icon">
          <circle cx="46" cy="78" r="6" />
          <path d="M 50.5 82.5 L 56 88 M 43 76 H 47 M 43 79 H 45" />
        </g>
        <text class="hub-label" x="48" y="122" text-anchor="middle">Documentation</text>
      </g>
    </svg>
    <figcaption class="trail-description">{{ accessibleDescription }}</figcaption>
  </figure>
</template>

<script>
export default {
  name: 'KnowledgeSearchTrail',
  props: {
    foundSources: { type: Array, default: () => [] },
    stage: { type: String, default: 'clustering' },
    reducedMotion: { type: Boolean, default: false },
  },
  data() {
    return {
      branches: [
        { id: 'certificates', label: 'Renewal', y: 30, path: 'M 69 80 H 102 C 133 80 129 30 160 30 H 192' },
        { id: 'bindings', label: 'Domain binding', y: 80, path: 'M 69 80 H 192' },
        { id: 'certificate-code', label: 'Application code', y: 130, path: 'M 69 80 H 102 C 133 80 129 130 160 130 H 192' },
      ],
    };
  },
  computed: {
    activeId() {
      if (this.stage !== 'researching') return '';
      return this.branches.find((branch) => !this.foundSources.includes(branch.id))?.id || '';
    },
    accessibleDescription() {
      const found = this.branches.filter((branch) => this.foundSources.includes(branch.id));
      const active = this.branches.find((branch) => branch.id === this.activeId);
      const progress = found.length
        ? `Found documentation for ${found.map((branch) => branch.label.toLowerCase()).join(', ')}.`
        : 'Documentation branches for renewal, domain binding, and application code.';
      return active ? `${progress} Looking for ${active.label.toLowerCase()}.` : progress;
    },
  },
};
</script>

